import{_ as t,o as a,c as s,a0 as n}from"./chunks/framework.C98-K6Ao.js";const m=JSON.parse('{"title":"Initiating Monads","description":"","frontmatter":{"layout":"doc","title":"Initiating Monads"},"headers":[],"relativePath":"Initiating-Monads.md","filePath":"Initiating-Monads.md"}'),o={name:"Initiating-Monads.md"};function i(d,e,r,h,c,l){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="initiating-monads" tabindex="-1">Initiating Monads <a class="header-anchor" href="#initiating-monads" aria-label="Permalink to &quot;Initiating Monads&quot;">​</a></h1><p>A monad is an Express HTTP runtime that holds a single <code>ME</code> kernel instance. It starts from one thing: a <strong>SEED</strong>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SEED</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">64-hex-string</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist/server.js</span></span></code></pre></div><p>The SEED is the namespace authority — the root from which the kernel derives every identity, path, and secret in that surface. Without it, the monad does not start.</p><h2 id="what-happens-at-startup" tabindex="-1">What happens at startup <a class="header-anchor" href="#what-happens-at-startup" aria-label="Permalink to &quot;What happens at startup&quot;">​</a></h2><ol><li><code>getKernel()</code> calls <code>new ME(process.env.SEED)</code> — once, as a singleton.</li><li>The kernel hydrates from <code>me-state/snapshot.json</code> if one exists (prior state).</li><li>The Express app mounts its routers: <code>/.monads/*</code>, <code>/me/*</code>, <code>/claims/*</code>, <code>/apps/*</code>, <code>/resolve</code>.</li><li>The monad registers itself with netget (see below).</li><li>The heartbeat loop starts — every <code>MONAD_NETGET_HEARTBEAT_MS</code> (default 3000ms), the monad re-reports its presence.</li></ol><h2 id="self-registration-with-netget" tabindex="-1">Self-registration with netget <a class="header-anchor" href="#self-registration-with-netget" aria-label="Permalink to &quot;Self-registration with netget&quot;">​</a></h2><p>Netget runs at a fixed address (<code>local.netget</code> / port 80 via nginx). Every monad can run on an arbitrary port — the port is chosen at startup and is unknown to netget until the monad announces it.</p><p>This is why <strong>monad registers with netget, not the other way around</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>monad Express (any port)</span></span>
<span class="line"><span>  └─ POST /apps/report → local.netget:80</span></span>
<span class="line"><span>       { name, port, host, metadata, health }</span></span></code></pre></div><p>Netget stores the entry in memory with a TTL of <code>4 × heartbeatMs</code>. If the heartbeat stops — monad crashed, was killed, or the process exited — the entry expires and netget considers that surface gone.</p><h2 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Purpose</th></tr></thead><tbody><tr><td><code>SEED</code> / <code>ME_SEED</code></td><td>✓</td><td>Namespace authority key</td></tr><tr><td><code>ME_NAMESPACE</code></td><td>—</td><td>Canonical rootspace name (e.g. <code>suis-macbook-air.local</code>)</td></tr><tr><td><code>MONAD_NAME</code></td><td>—</td><td>Human name of this surface instance</td></tr><tr><td><code>MONAD_PRIVATE_KEY</code></td><td>—</td><td>Ed25519 surface identity key — generate and persist one per instance</td></tr><tr><td><code>ME_STATE_DIR</code></td><td>—</td><td>Where <code>snapshot.json</code> lives (default: <code>me-state/</code>)</td></tr></tbody></table><h2 id="multiple-monads-one-namespace" tabindex="-1">Multiple monads, one namespace <a class="header-anchor" href="#multiple-monads-one-namespace" aria-label="Permalink to &quot;Multiple monads, one namespace&quot;">​</a></h2><p>Several monad processes can share the same <code>ME_NAMESPACE</code> (e.g. <code>monad:cleaker</code>, <code>monad:netget</code>). Each reports separately to netget under a different <code>name</code>. Netget&#39;s mesh scoring picks the healthiest one when routing a request — this is <strong>subtractive synthesis</strong>: the namespace stays stable while individual monads come and go.</p>`,15)])])}const g=t(o,[["render",i]]);export{m as __pageData,g as default};
